edits.newText:
finishMail() {
  const q = this.data.mail.quest;
  if (q) {
    const memory = this.data.mail.memory ?? {};
    const toItems = memory[q.to] ?? [];
    toItems.unshift(q.item);
    memory[q.to] = toItems.slice(0, 3);
    this.data.mail.memory = memory;
  }
  this.data.mail.quest = null;
  this.data.mail.delivered += 1;
  this.data.quests.active = null;
  this.commit();
}

